import{_ as a,o as n,c as o,l as r,t as s,N as t}from"./chunks/framework.Bbd9fWQx.js";const _=JSON.parse('{"title":"docker-container-pause | x-cmd man (docker man1) | Pause all processes within one or more\\ncontainers","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-container-pause - Pause all processes within one or more\\ncontainers","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-container-pause | x-cmd man (docker man1) | Pause all processes within one or more\\ncontainers"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-container-pause - Pause all processes within one or more\\ncontainers"}]]},"headers":[],"params":{"isMan":true,"man":"docker-container-pause","category":"docker man1","desc":"Pause all processes within one or more\\ncontainers"},"relativePath":"docker/man1/docker-container-pause.md","filePath":"docker/man1/docker-container-pause.md"}'),c={name:"docker/man1/docker-container-pause.md"},i={class:"visually-hidden"},d=t('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-container-pause - Pause all processes within one or more containers</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker container pause CONTAINER [CONTAINER...]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>docker container pause</strong> command suspends all processes in the specified containers. On Linux, this uses the freezer cgroup. Traditionally, when suspending a process the <strong>SIGSTOP</strong> signal is used, which is observable by the process being suspended. With the freezer cgroup the process is unaware, and unable to capture, that it is being suspended, and subsequently resumed. On Windows, only Hyper-V containers can be paused.</p><p>See the freezer cgroup documentation ⟨<a href="https://www.kernel.org/doc/Documentation/cgroup-v1/freezer-subsystem.txt%E2%9F%A9" target="_blank" rel="noreferrer">https://www.kernel.org/doc/Documentation/cgroup-v1/freezer-subsystem.txt⟩</a> for further details.</p><p><strong>docker-container-unpause(1)</strong> to unpause all processes within a container.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-h</strong>, <strong>--help</strong>[=false] help for pause</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-container(1)</strong></p>',12);function p(e,l,u,h,m,g){return n(),o("div",null,[r("h1",i,s(e.$params.man),1),d])}const f=a(c,[["render",p]]);export{_ as __pageData,f as default};
